import unittest
from candidate import correct_bracketing

class TestBracketing(unittest.TestCase):
    def test_correct_bracketing_empty_string(self):
        self.assertTrue(correct_bracketing(""))

    def test_correct_bracketing_single_open_bracket(self):
        self.assertFalse(correct_bracketing("("))

    def test_correct_bracketing_single_close_bracket(self):
        self.assertFalse(correct_bracketing(")"))

    def test_correct_bracketing_open_close_brackets(self):
        self.assertTrue(correct_bracketing("()"))

    def test_correct_bracketing_nested_brackets(self):
        self.assertTrue(correct_bracketing("(()())"))

    def test_correct_bracketing_mismatched_brackets(self):
        self.assertFalse(correct_bracketing(")(())"))

    def test_correct_bracketing_unbalanced_brackets(self):
        self.assertFalse(correct_bracketing("())("))

    def test_correct_bracketing_None_input(self):
        with self.assertRaises(TypeError):
            correct_bracketing(None)

    def test_correct_bracketing_non_string_input(self):
        with self.assertRaises(TypeError):
            correct_bracketing(123)

    def test_correct_bracketing_string_with_non_bracket_characters(self):
        with self.assertRaises(ValueError):
            correct_bracketing("(abc)")

if __name__ == '__main__':
    unittest.main()
